-- Expanded spell catalogue: additional 1st-5th level spells from the 2014 PHB.
-- All rows have campaign_id = null (shared SRD catalogue).

insert into spells (name, level, school, casting_time, range, verbal, somatic, material, duration, concentration, ritual, classes, description, tags) values
-- 1st level
('Burning Hands', 1, 'evocation', '1 action', 'Self (15-foot cone)', true, true, false, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'As you hold your hands with thumbs touching and fingers spread, a thin sheet of roaring flame springs from your palms. Each creature in a 15-foot cone must make a Dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one. The fire ignites any flammable objects in the area that aren''t being worn or carried.', array['1st-level', 'damage', 'evocation']),
('Disguise Self', 1, 'illusion', '1 action', 'Self', true, true, false, '1 hour', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'You make yourself—including your clothing, armor, weapons, and other belongings on your person—look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You have no ability to change your body parts fundamentally. You decide what you look like, including features, height, weight, hair length, coloration, scars, and distinguishing characteristics, if any.', array['1st-level', 'illusion', 'utility']),
('Feather Fall', 1, 'transmutation', '1 reaction, which you take when you or a creature within 60 feet of you falls', '60 feet', true, false, false, '1 minute', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'Choose up to five falling creatures within range. A falling creature''s rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature.', array['1st-level', 'utility', 'transmutation']),
('Fog Cloud', 1, 'conjuration', '1 action', '120 feet', true, true, false, 'Concentration, up to 1 hour', true, false, array['Druid', 'Ranger', 'Sorcerer', 'Wizard'], 'You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is lightly obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.', array['1st-level', 'control', 'conjuration']),
('Grease', 1, 'conjuration', '1 action', '60 feet', true, true, true, '1 minute', false, false, array['Sorcerer', 'Wizard'], 'Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration. When the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a Dexterity saving throw or fall prone.', array['1st-level', 'control', 'conjuration']),
('Hex', 1, 'enchantment', '1 bonus action', '90 feet', true, false, false, 'Concentration, up to 1 hour', true, false, array['Warlock'], 'You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 necrotic damage to the target whenever you hit it with an attack. Also, choose one ability when you cast the spell. The target has disadvantage on ability checks made with the chosen ability.', array['1st-level', 'control', 'enchantment']),
('Jump', 1, 'transmutation', '1 action', 'Touch', true, true, true, '1 minute', false, false, array['Druid', 'Ranger', 'Sorcerer', 'Wizard'], 'You touch a creature. The creature''s jump distance is tripled until the spell ends.', array['1st-level', 'buff', 'transmutation']),
('Longstrider', 1, 'transmutation', '1 action', 'Touch', true, true, true, '1 hour', false, false, array['Bard', 'Druid', 'Ranger', 'Wizard'], 'You touch a creature. The target''s speed increases by 10 feet until the spell ends.', array['1st-level', 'buff', 'transmutation']),
('Protection from Evil and Good', 1, 'abjuration', '1 action', 'Touch', true, true, true, 'Concentration, up to 10 minutes', true, false, array['Cleric', 'Paladin', 'Warlock', 'Wizard'], 'Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, dragons, elementals, fey, fiends, giants, undead. The protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can''t be charmed, frightened, or possessed by them.', array['1st-level', 'defense', 'abjuration']),
('Thorn Whip', 1, 'transmutation', '1 action', '30 feet', true, true, false, 'Instantaneous', false, false, array['Druid'], 'You create a long, vine-like whip covered in thorns that lashes out at your command toward a creature in range. Make a melee spell attack against the target. If the attack hits, the creature takes 1d6 piercing damage, and if the creature is Large or smaller, you pull the creature up to 5 feet closer to you.', array['1st-level', 'damage', 'transmutation']),
-- 2nd level
('Aid', 2, 'abjuration', '1 action', '30 feet', true, true, true, '8 hours', false, false, array['Bard', 'Cleric', 'Paladin'], 'Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each creature gains 5 temporary hit points for the duration. When you cast this spell using a spell slot of 3rd level or higher, the temporary hit points increase by 5 for each slot level above 2nd.', array['2nd-level', 'buff', 'abjuration']),
('Barkskin', 2, 'transmutation', '1 action', 'Touch', true, true, true, 'Concentration, up to 1 hour', true, false, array['Druid', 'Ranger'], 'You touch a willing creature. Until the spell ends, the target''s skin has a rough, bark-like appearance, and the target''s AC can''t be less than 16, regardless of what kind of armor it is wearing.', array['2nd-level', 'defense', 'transmutation']),
('Blindness/Deafness', 2, 'necromancy', '1 action', '30 feet', true, true, false, '1 minute', false, false, array['Bard', 'Cleric', 'Sorcerer', 'Wizard'], 'For the spell''s duration, a creature you can see within range is either blinded or deafened of your choice. At the end of each of the creature''s turns, it can make a Constitution saving throw. On a success, the spell ends.', array['2nd-level', 'control', 'necromancy']),
('Blur', 2, 'illusion', '1 action', 'Self', true, true, false, 'Concentration, up to 1 minute', true, false, array['Sorcerer', 'Wizard'], 'Your body becomes blurred, shifting and wavering to all who can see you. For the spell''s duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn''t rely on sight, as with blindsight, or can see through illusions, as with truesight.', array['2nd-level', 'defense', 'illusion']),
('Darkness', 2, 'evocation', '1 action', '60 feet', true, true, true, 'Concentration, up to 10 minutes', true, false, array['Sorcerer', 'Warlock', 'Wizard'], 'Magical darkness spreads from a point of your choice within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can''t see through this darkness, and nonmagical light can''t illuminate it. If the point of darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled.', array['2nd-level', 'control', 'evocation']),
('Darkvision', 2, 'transmutation', '1 action', 'Touch', true, true, true, '8 hours', false, false, array['Druid', 'Ranger', 'Sorcerer', 'Wizard'], 'You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet.', array['2nd-level', 'buff', 'transmutation']),
('Gust of Wind', 2, 'evocation', '1 action', 'Self (60-foot line)', true, true, true, 'Concentration, up to 1 minute', true, false, array['Druid', 'Sorcerer', 'Wizard'], 'A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell''s duration. Each creature that starts its turn in the line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the line. Any creature that is Large or smaller can be pushed up to 15 feet. Any object that is completely in the line of the gust is pushed 15 feet away from you.', array['2nd-level', 'control', 'evocation']),
('Mirror Image', 2, 'illusion', '1 action', 'Self', true, true, false, 'Concentration, up to 1 minute', true, false, array['Sorcerer', 'Wizard'], 'Three illusory copies of yourself appear in your space. Until the spell ends, the copies move with you and mimic your actions, shifting position so it''s impossible to track which image is real. You can use your action to dismiss the illusory copies. Each time a creature targets you with an attack during the spell''s duration, roll a d20 to determine whether the attack instead targets one of your copies.', array['2nd-level', 'defense', 'illusion']),
('Pass Without Trace', 2, 'transmutation', '1 action', 'Self (30-foot radius)', true, true, true, 'Concentration, up to 1 hour', true, false, array['Druid', 'Ranger'], 'A veil of shadows and silence radiates from you. For the duration, each creature with you gains a +10 bonus to Dexterity (Stealth) checks and can''t be tracked by nonmagical means, only by magic. Creatures that don''t know about your Spellcasting might perceive the figures as creatures that are simply staying very still.', array['2nd-level', 'utility', 'transmutation']),
('Ray of Enfeeblement', 2, 'necromancy', '1 action', '60 feet', true, true, false, 'Concentration, up to 1 minute', true, false, array['Warlock', 'Wizard'], 'A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.', array['2nd-level', 'damage', 'necromancy']),
('Suggestion', 2, 'enchantment', '1 action', '30 feet', true, false, true, 'Concentration, up to 8 hours', true, false, array['Bard', 'Sorcerer', 'Warlock', 'Wizard'], 'You suggest a course of activity, phrased in a sentence or two, to a creature that you can see within range and that can hear and understand you. Creatures that can''t be charmed are immune to this effect. The suggestion must sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some obviously harmful act ends the spell.', array['2nd-level', 'control', 'enchantment']),
('Web', 2, 'conjuration', '1 action', '60 feet', true, true, true, 'Concentration, up to 1 hour', true, false, array['Sorcerer', 'Wizard'], 'You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain, and its area is lightly obscured. If the webs aren''t anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses in on itself and the spell ends at the start of your next turn. Creatures can use their action to make a Strength check against your spell save DC to clear away enough webbing to allow passage through the web.', array['2nd-level', 'control', 'conjuration']),
-- 3rd level
('Animate Dead', 3, 'necromancy', '1 minute', '10 feet', true, true, true, 'Instantaneous', false, false, array['Cleric', 'Wizard'], 'You can cast this spell only at night. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as a ghoul under your control. The target becomes a ghoul for the duration. At the end of the duration, the target collapses back into inanimate bone.', array['3rd-level', 'control', 'necromancy']),
('Bestow Curse', 3, 'necromancy', '1 action', 'Touch', true, true, false, 'Concentration, up to 1 minute', true, false, array['Bard', 'Cleric', 'Wizard'], 'You touch a creature, and that creature must succeed on a Wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options. Each option involves different mechanics and effects depending on the curse chosen.', array['3rd-level', 'control', 'necromancy']),
('Blink', 3, 'transmutation', '1 action', 'Self', true, false, false, '1 minute', false, false, array['Sorcerer', 'Wizard'], 'Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane. At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from.', array['3rd-level', 'utility', 'transmutation']),
('Call Lightning', 3, 'evocation', '1 action', '120 feet', true, true, false, 'Concentration, up to 10 minutes', true, false, array['Cleric', 'Druid'], 'A storm cloud appears in the shape of a cylinder that is 60 feet tall with a 120-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can''t see a point in the air where the storm cloud could appear (for example, if you''re in a room that can''t accommodate the cloud). When you cast the spell, choose a point you can see within range. A bolt of lightning springs from the cloud to that point. Each creature within 5 feet of that point must make a Dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much on a successful one.', array['3rd-level', 'damage', 'evocation']),
('Conjure Animals', 3, 'conjuration', '1 action', '60 feet', true, true, true, 'Concentration, up to 1 hour', true, false, array['Druid', 'Ranger'], 'You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: One beast of challenge rating 2 or lower; two beasts of challenge rating 1 or lower; four beasts of challenge rating 1/4 or lower; eight beasts of challenge rating 1/8 or lower. Each beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.', array['3rd-level', 'conjuration', 'control']),
('Daylight', 3, 'evocation', '1 action', '60 feet', true, true, false, '1 hour', false, false, array['Cleric', 'Druid', 'Paladin', 'Ranger', 'Sorcerer', 'Wizard'], 'A sphere of daylight springs from your hand. The sphere is bright light out to 60 feet and dim light 60 feet beyond that. If you chose a point on an object you are holding or one that isn''t being worn or carried, the light emanates from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a bag, blocks the light. If any of this spell''s area overlaps with an area of magical darkness created by a spell of 3rd level or lower, that magical darkness is dispelled.', array['3rd-level', 'evocation', 'utility']),
('Dispel Magic', 3, 'abjuration', '1 action', '120 feet', true, false, false, 'Instantaneous', false, false, array['Bard', 'Cleric', 'Druid', 'Paladin', 'Ranger', 'Sorcerer', 'Warlock', 'Wizard'], 'Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell''s level. On a successful check, the spell ends.', array['3rd-level', 'utility', 'abjuration']),
('Fear', 3, 'illusion', '1 action', 'Self (30-foot cone)', true, true, false, 'Concentration, up to 1 minute', true, false, array['Sorcerer', 'Warlock', 'Wizard'], 'You project the image of a creature you can see within range into a 30-foot cone originating from you. Each creature in that area must succeed on a Wisdom saving throw or drop whatever it is holding and become frightened for the duration. While frightened by this spell, a creature must take the Dash action on each of its turns to move away from you by the shortest and most direct route, unless there is nowhere to move.', array['3rd-level', 'control', 'illusion']),
('Fly', 3, 'transmutation', '1 action', 'Touch', true, true, true, 'Concentration, up to 1 hour', true, false, array['Sorcerer', 'Warlock', 'Wizard'], 'You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.', array['3rd-level', 'buff', 'transmutation']),
('Lightning Bolt', 3, 'evocation', '1 action', 'Self (100-foot line)', true, true, false, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.', array['3rd-level', 'damage', 'evocation']),
('Revivify', 3, 'necromancy', '1 action', 'Touch', true, true, true, 'Instantaneous', false, false, array['Bard', 'Cleric', 'Paladin'], 'You touch a creature that has been dead for no more than 1 minute. That creature returns to life with 1 hit point. This spell can''t return to life a creature that has died of old age, nor can it restore any missing body parts.', array['3rd-level', 'healing', 'necromancy']),
('Sleet Storm', 3, 'conjuration', '1 action', '150 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Druid', 'Sorcerer', 'Wizard'], 'Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is difficult terrain, and nonmagical flame is extinguished in the area. The ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell''s area for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or fall prone.', array['3rd-level', 'control', 'conjuration']),
('Stinking Cloud', 3, 'conjuration', '1 action', '90 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Bard', 'Sorcerer', 'Wizard'], 'A foul-smelling cloud of noxious gas springs from a point of your choice within range. The cloud fills a 20-foot-radius sphere, moving away from the point you chose in a direction you choose as long as it remains within the spell''s duration. Each creature that is completely within the cloud at the start of its turn must succeed on a Constitution saving throw or spend its action that turn retching and reeling.', array['3rd-level', 'control', 'conjuration']),
-- 4th level
('Arcane Eye', 4, 'divination', '1 action', '30 feet', true, true, true, 'Concentration, up to 1 hour', true, false, array['Wizard'], 'For the spell''s duration, you can use an action to see through the eye''s point of view as if you were looking at it. While you are doing so, you can''t see anything else. Information gathered through the eye can only be perceived through normal vision.', array['4th-level', 'utility', 'divination']),
('Blight', 4, 'necromancy', '1 action', '30 feet', true, true, false, 'Instantaneous', false, false, array['Druid', 'Sorcerer', 'Warlock', 'Wizard'], 'Necromantic energy springs from a point of your choice within range. Each creature in that area must make a Constitution saving throw. A creature takes 8d8 necrotic damage on a failed save, or half as much on a successful one. You can''t damage a plant creature with this spell.', array['4th-level', 'damage', 'necromancy']),
('Confusion', 4, 'enchantment', '1 action', '90 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Bard', 'Druid', 'Sorcerer', 'Wizard'], 'Each creature that starts its turn in a 10-foot-radius sphere centered on a point of your choice within range must succeed on a Wisdom saving throw when it sees you cast this spell or when it enters the spell''s area if it fails that save. On a failed save, roll a d8 to determine what the creature does during its turn.', array['4th-level', 'control', 'enchantment']),
('Dimension Door', 4, 'conjuration', '1 action', '500 feet', true, false, false, 'Instantaneous', false, false, array['Bard', 'Sorcerer', 'Warlock', 'Wizard'], 'You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as 200 feet straight downward or 300 feet north-northeast. If you would arrive in a place occupied by an object or creature, you are shunted to the nearest unoccupied space that you can occupy.', array['4th-level', 'utility', 'conjuration']),
('Greater Invisibility', 4, 'illusion', '1 action', 'Touch', true, true, false, 'Concentration, up to 1 minute', true, false, array['Bard', 'Sorcerer', 'Wizard'], 'You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target''s person. Unlike invisibility, the target can attack and cast spells, making this spell superior for combat situations.', array['4th-level', 'invisibility', 'illusion']),
('Hallucinatory Terrain', 4, 'illusion', '10 minutes', '300 feet', true, true, true, '24 hours', false, false, array['Bard', 'Druid', 'Warlock', 'Wizard'], 'You make terrain in a 150-foot cube in range look, sound, and smell like some other sort of terrain. The terrain''s general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.', array['4th-level', 'illusion', 'utility']),
('Polymorph', 4, 'transmutation', '1 action', '60 feet', true, true, true, 'Concentration, up to 1 hour', true, false, array['Bard', 'Druid', 'Sorcerer', 'Wizard'], 'This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a Wisdom saving throw to avoid the effect. The creature is limited to a challenge rating equal to its level (or the level approximate to its challenge rating) and can''t be undead or a construct. The creature retains its alignment and personality.', array['4th-level', 'transmutation', 'buff']),
('Wall of Fire', 4, 'evocation', '1 action', '120 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Druid', 'Sorcerer', 'Wizard'], 'You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration. When the wall appears, each creature within its area must make a Dexterity saving throw. A creature takes 5d8 fire damage on a failed save, or half as much on a successful one.', array['4th-level', 'damage', 'evocation']),
-- 5th level
('Animate Objects', 5, 'transmutation', '1 action', '120 feet', true, true, false, 'Concentration, up to 1 minute', true, false, array['Bard', 'Sorcerer', 'Wizard'], 'Objects come alive at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects. You can''t animate any object larger than Huge. Each object animates and becomes a creature under your control until the spell ends or until an animated object drops to 0 hit points.', array['5th-level', 'conjuration', 'control']),
('Cone of Cold', 5, 'evocation', '1 action', 'Self (60-foot cone)', true, true, true, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'A blast of cold air springs from your hands. Each creature in a 60-foot cone must make a Constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.', array['5th-level', 'damage', 'evocation']),
('Conjure Elemental', 5, 'conjuration', '1 minute', '90 feet', true, true, true, 'Concentration, up to 1 hour', true, false, array['Druid', 'Wizard'], 'You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An attuned elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.', array['5th-level', 'conjuration', 'control']),
('Dominate Person', 5, 'enchantment', '1 action', '60 feet', true, true, false, 'Concentration, up to 1 minute', true, false, array['Bard', 'Sorcerer', 'Wizard'], 'You attempt to beguile a humanoid that you can see within range. It must succeed on a Wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw. While the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious.', array['5th-level', 'control', 'enchantment']),
('Feeblemind', 5, 'enchantment', '1 action', '150 feet', true, true, true, 'Instantaneous', false, false, array['Bard', 'Druid', 'Warlock', 'Wizard'], 'You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an Intelligence saving throw. On a failed save, the creature''s Intelligence and Charisma scores become 1. The creature can''t cast spells, activate magical items, or understand language in any form. If the target later regains any of its Intelligence or Charisma, the spell ends.', array['5th-level', 'damage', 'enchantment']),
('Geas', 5, 'enchantment', '1 minute', '60 feet', true, false, false, '30 days', false, false, array['Bard', 'Cleric', 'Druid', 'Paladin', 'Wizard'], 'You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a Wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day.', array['5th-level', 'control', 'enchantment']),
('Greater Restoration', 5, 'abjuration', '1 action', 'Touch', true, true, true, 'Instantaneous', false, false, array['Bard', 'Cleric', 'Druid', 'Paladin'], 'You imbue a creature you touch with positive energy to undo a debilitating effect. You can, for example, remove a disease and its effects if the target is poisoned, remove a curse, end one spell affecting the target, or restore one ability score reduced by disease or injury to its normal maximum value.', array['5th-level', 'healing', 'abjuration']),
('Scrying', 5, 'divination', '10 minutes', 'Self', true, true, true, 'Concentration, up to 1 hour', true, false, array['Bard', 'Cleric', 'Druid', 'Warlock', 'Wizard'], 'You can see and hear a particular creature that you choose within range and that you have met before. The creature must make a Wisdom saving throw, which is modified by how well you know the subject and the sort of physical connection you have to it. If it succeeds, the creature resists this magical scrying, and you can''t use this spell against it again for 24 hours.', array['5th-level', 'divination', 'utility']),
('Telekinesis', 5, 'transmutation', '1 action', '60 feet', true, false, false, 'Concentration, up to 10 minutes', true, false, array['Sorcerer', 'Wizard'], 'You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each turn until the spell ends, you can exert your will on one creature or object that you can see within range, causing the appropriate effect. You can affect the same creature or object if you are concentrating on it for the whole duration or switch to a new one at any time. If you switch targets, the previous creature or object is no longer affected by the spell.', array['5th-level', 'transmutation', 'utility']),
('Teleportation Circle', 5, 'conjuration', '1 minute', '10 feet', true, true, true, '1 round', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'As you cast the spell, you draw a glowing circle on the ground or other surface. The circle is 10 feet in diameter and glows with soft blue light, remaining visible for 1 minute. When the circle is complete, teleportation magic fills it, and any creature that enters the circle instantly appears in an unoccupied space near a destination circle you know about, such as one you created with a previous casting of this spell or one you have seen elsewhere.', array['5th-level', 'conjuration', 'utility']);
